/* The drop-in memtrack path (Task 2.5): AnalysisModeMemtrack.bc forwards
 * analysis_init and the memory calls to these entry points. */
static void *harness_slot;

static void scenario_memtrack_rt_double_free(void) {
    map2check_init(0);
    __m2c_rt_memtrack_analysis_init();
    void *block = malloc(16);
    harness_slot = block;
    __m2c_rt_memtrack_map2check_alloca("p", &harness_slot, 8, 8, 1, 1);
    __m2c_rt_memtrack_map2check_malloc(block, 16);
    __m2c_rt_memtrack_map2check_add_store_pointer(&harness_slot, block, 1, "p", 2, "main");
    __m2c_rt_memtrack_map2check_free("p", &harness_slot, 1, 3, "main");
    free(block);
    __m2c_rt_memtrack_map2check_free("p", &harness_slot, 1, 4, "main");
}

static void scenario_memtrack_rt_cstring(void) {
    map2check_enable_witness();
    map2check_init(0);
    __m2c_rt_memtrack_analysis_init();
    char *s = malloc(4);
    memcpy(s, "abcd", 4);
    __m2c_rt_memtrack_map2check_malloc(s, 4);
    __m2c_rt_memtrack_map2check_check_cstring(s);
    __m2c_rt_memtrack_map2check_check_deref(5, "main");
}

static void scenario_memtrack_rt_leak(void) {
    map2check_init(0);
    __m2c_rt_memtrack_analysis_init();
    void *block = malloc(8);
    __m2c_rt_memtrack_map2check_malloc(block, 8);
    __m2c_rt_memtrack_analysis_generate_aux_witness_files();
    if (__m2c_rt_memtrack_analysis_is_program_correct() != 0) {
        _exit(91);
    }
    free(block);
    map2check_success();
}

static int test_analysis_modes(void) {
    if (run_mode_scenario(scenario_none_mode, 0, "NONE\n", NULL, NULL)) {
        return 1;
    }
    if (run_mode_scenario(scenario_memtrack_deref, 1,
                          "FALSE-DEREF\nLine: 1\nFunction: main\n",
                          "map2check_checked_error", NULL)) {
        return 2;
    }
    if (run_mode_scenario(scenario_memtrack_deref_witness, 1,
                          "FALSE-DEREF\nLine: 1\nFunction: main\n",
                          "map2check_checked_error", "END OF TIME\n")) {
        return 3;
    }
    if (run_mode_scenario(scenario_assert_ignores_overflow, 0, "NONE\n", NULL,
                          NULL)) {
        return 4;
    }
    if (run_mode_scenario(scenario_target, 1,
                          "TARGET-REACHED\nLine: 12\nFunction: reach_error\n",
                          NULL, NULL)) {
        return 5;
    }
    if (run_mode_scenario(scenario_out_of_range_keeps_target, 0, "NONE\n",
                          NULL, NULL)) {
        return 6;
    }
    if (run_mode_scenario(scenario_memcleanup_unreferenced, 0, "NONE\n", NULL,
                          NULL)) {
        return 7;
    }
    if (run_mode_scenario(scenario_memcleanup_referenced, 1,
                          "FALSE-MEMCLEANUP\n", "map2check_property_memcleanup",
                          "FALSE-MEMCLEANUP\n")) {
        return 8;
    }
    if (run_mode_scenario(scenario_overflow_rt_add, 1,
                          "OVERFLOW\nLine: 20\nFunction: main\n",
                          "map2check_property_overflow",
                          "OVERFLOW\nLine: 20\nFunction: main\n")) {
        return 9;
    }
    if (run_mode_scenario(scenario_overflow_rt_srem, 1,
                          "FALSE-DIVBYZERO\nLine: 7\nFunction: main\n",
                          "map2check_property_overflow", NULL)) {
        return 10;
    }
    if (run_mode_scenario(scenario_assert_rt, 1,
                          "ASSERT\nLine: 21\nFunction: main\n",
                          "map2check_property_assert",
                          "ASSERT\nLine: 21\nFunction: main\n")) {
        return 11;
    }
    if (run_mode_scenario(scenario_none_rt_target, 1,
                          "TARGET-REACHED\nLine: 22\nFunction: reach_error\n",
                          NULL, NULL)) {
        return 12;
    }
    if (run_mode_scenario(scenario_memtrack_rt_double_free, 1,
                          "FALSE-FREE\nLine: 4\nFunction: main\n",
                          "map2check_property_free",
                          "FALSE-FREE\nLine: 4\nFunction: main\n")) {
        return 13;
    }
    if (run_mode_scenario(scenario_memtrack_rt_cstring, 1,
                          "FALSE-DEREF\nLine: 5\nFunction: main\n",
                          "map2check_checked_error", "END OF TIME\n")) {
        return 14;
    }
    /* analysis_is_program_correct wrote FALSE-MEMTRACK and released the
     * leak; map2check_success then overwrites map2check_property with NONE. */
    if (run_mode_scenario(scenario_memtrack_rt_leak, 0, "NONE\n",
                          "map2check_property_memtrack", "FALSE-MEMTRACK\n")) {
        return 15;
    }
    return 0;
}

int main(void) {
    if (MAP2CHECK_VERSION[0] == '\0') {
        return 1;
    }

    /* round 0: all exports before map2check_init() (issue #8) */
    run_pre_init_boundary();

    if (test_result_and_control_flags() != 0) {
        return 1;
    }

    /* round 1: adversarial inputs before init */
    run_bad_inputs();

    /* round 2: well-formed use of every export after init */
    map2check_init(0);
    run_valid_pass();

    /* explicit reset between "runs" */
    map2check_reset();

    /* round 3: adversarial inputs again, post-reset */
    run_bad_inputs();

    /* two consecutive LibFuzzer iterations must start from independent
     * state (see rust/src/nondet/libfuzzer.rs: state::reset() per call). */
    {
        const uint8_t first_input[] = {0x01, 0x02, 0x03, 0x04};
        const uint8_t second_input[] = {0xa0, 0xb0};
        if (LLVMFuzzerTestOneInput(first_input, sizeof(first_input)) != 0 ||
            LLVMFuzzerTestOneInput(second_input, sizeof(second_input)) != 0) {
            return 1;
        }
    }

    {
        int failed_mode = test_analysis_modes();
        if (failed_mode != 0) {
            fprintf(stderr, "test_analysis_modes: scenario %d failed\n",
                    failed_mode);
            return 1;
        }
    }

    /* A failed __VERIFIER_assume abandons only the current input: the
     * unwind crosses __map2check_main__ (a C frame), LLVMFuzzerTestOneInput
     * returns 0, and the next input runs (develop: nondet_cancel). */
    /* An exit(0) instead of the unwind would also end with status 0, so
     * from here on an early exit is turned into a failure. Registered after
     * the forking scenarios above, whose children exit on purpose. */
    atexit(harness_require_completion);
    {
        const uint8_t rejected[] = {0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00};
        const uint8_t accepted[] = {0x00, 0x00, 0x00, 0x00, 0x07, 0x00, 0x00, 0x00};
        const uint8_t wrapped[] = {0x07};
        harness_reject_inputs = 1;
        for (int i = 0; i < 100; i++) {
            if (LLVMFuzzerTestOneInput(rejected, sizeof(rejected)) != 0) {
                return 1;
            }
        }
        if (harness_after_assume != 0) {
            fprintf(stderr, "assume did not abandon the input\n");
            return 1;
        }
        if (LLVMFuzzerTestOneInput(accepted, sizeof(accepted)) != 0 ||
            harness_after_assume != 1) {
            fprintf(stderr, "accepted input did not run to the end\n");
            return 1;
        }
        /* {0x07}: pchar length 0x07070707 (capped, 4095 chars from the
         * wrap), then x reads 07 07 07 07: rejected. */
        if (LLVMFuzzerTestOneInput(wrapped, sizeof(wrapped)) != 0 ||
            harness_after_assume != 1) {
            return 1;
        }
        harness_reject_inputs = 0;
    }

    harness_completed = 1;
    map2check_success();
    return 0;
}
